// Lazy loader for the bundled built-in deck corpus (5,013 decks).
//
// The asset (`bundledDecks.generated.json`, ~5.5 MB, generated by
// `web/scripts/build-bundled-decks.mjs`) is a static, content-hashed Vite asset
// served via `?url`. Parsing 5.5 MB of JSON is tens of ms of main-thread work,
// so it must NOT run on the synchronous login path — the offline-image-index
// lesson (`main.tsx` warms `loadImageIndex()` fire-and-forget, `cards/offlineIndex.ts`).
//
// Contract:
//   - importing this module does no I/O — no top-level fetch, and no top-level
//     `?url` import either: the asset URL is resolved inside `loadBundledCorpus()`
//     (synchronously in dev/test, via a dynamic import in prod builds), so
//     plain-Node importers of the deck modules (the e2e specs, via
//     fixtures/deck-names.ts → lobby/decks) never trip the Vite-only `?url`
//     query at load time;
//   - `loadBundledCorpus()` is the only entry point that fetches, is idempotent
//     and caches the parsed decks for the session;
//   - `bundledCorpusDecks()` is the synchronous view the picker/gallery read —
//     empty until the corpus lands, then the 5,013 decks;
//   - a failed load is not cached (the next call retries).

import type { Deck } from '../lobby/decks'
import type { BundledDeckEntry, BundledDecksFile, BundledDecksManifest } from './builtinDecklist'
import { expandBundledCard } from './builtinDecklist'
import { normalizeDeckCards } from './deckNormalize'
import { sortBundledEntries } from './deckOrder'

/** The asset URL — '' until the loader resolves it on first load. */
let assetUrl = ''

/**
 * The `?url` of the committed asset as cached from the first load — '' before
 * any load. A getter, not a module constant: under dev/test the URL is derived
 * synchronously (the source tree is served at its root-relative path), in a
 * production build it only becomes knowable once the dynamic `?url` import
 * inside `loadBundledCorpus()` has resolved (the old top-level `?url` import
 * made this module un-importable from plain Node, killing the 44 e2e specs
 * that reach it via fixtures/deck-names.ts). Still exported so a test can pin
 * the fetched URL.
 */
export function bundledDecksAssetUrl(): string {
  return assetUrl
}

let manifest: BundledDecksManifest | null = null
let decks: Deck[] | null = null
let loadPromise: Promise<Deck[]> | null = null

function toDeck(entry: BundledDeckEntry): Deck {
  // Basic lands arrive plain (empty printing) and get their preset printing
  // filled in here, client-side, exactly like an imported text decklist.
  return {
    id: entry.id,
    name: entry.name,
    // The library travels with the deck: it is what groups the deck pickers
    // (`deckOrder.deckPickerSections`).
    group: entry.group,
    cards: normalizeDeckCards(entry.cards.map(expandBundledCard)),
    sideboard: normalizeDeckCards(entry.sideboard.map(expandBundledCard)),
  }
}

/** Manifest of the loaded corpus (deck count + per-format breakdown), or null. */
export function bundledCorpusManifest(): BundledDecksManifest | null {
  return manifest
}

/** True once the corpus is in memory. */
export function bundledCorpusLoaded(): boolean {
  return decks !== null
}

/** Synchronous view: the corpus decks if loaded, otherwise an empty list. */
export function bundledCorpusDecks(): Deck[] {
  return decks ?? []
}

/** Test seam: inject decks (and manifest) without fetching. */
export function setBundledCorpusForTests(
  testDecks: Deck[] | null,
  testManifest: BundledDecksManifest | null = null,
): void {
  decks = testDecks
  manifest = testManifest
  loadPromise = null
}

/**
 * Resolve the asset URL once, then fetch + parse the corpus once. Idempotent:
 * the resolved URL is cached, concurrent callers share the same promise; a
 * rejection clears it so a later call retries.
 */
export function loadBundledCorpus(): Promise<Deck[]> {
  if (decks) return Promise.resolve(decks)
  if (loadPromise) return loadPromise
  loadPromise = (async () => {
    // The URL resolution must not cost a real async hop before the first
    // fetch: `useDeckChoices` parks `fetch` and releases the corpus from the
    // first call's tick (a module-runner round trip defers the fetch past the
    // wizard's mount flush, and the parked test never lands). In dev/test the
    // source tree is served at its root-relative path — the same string the
    // `?url` import yields — so it is derived synchronously there; a
    // production build (no source tree, content-hashed asset) keeps the
    // dynamic `?url` import, which stays out of plain Node's reach because
    // only this loader ever evaluates it. Inside the try so a failed URL
    // resolution is not cached either (the contract below).
    try {
      if (!assetUrl) {
        if (import.meta.env?.DEV) {
          assetUrl = `${import.meta.env?.BASE_URL ?? '/'}src/data/bundledDecks.generated.json`
        } else {
          const mod = (await import('../data/bundledDecks.generated.json?url')) as { default: string }
          assetUrl = mod.default
        }
      }
      const res = await fetch(assetUrl)
      if (!res.ok) throw new Error(`bundled decks asset failed: ${assetUrl} -> ${res.status}`)
      const file = (await res.json()) as BundledDecksFile
      manifest = file.manifest
      // The asset carries the corpus's FILE order; the old webui's library →
      // deck-name order is applied here, once, so every consumer (the Create
      // Table pickers, the join dialog, the gallery) sees the same sorted list.
      decks = sortBundledEntries(file.decks).map(toDeck)
      return decks
    } catch (err) {
      // A failed load is not cached: neither the in-flight promise nor the
      // decks — the next call retries the whole sequence.
      loadPromise = null
      throw err
    }
  })()
  return loadPromise
}
